package com.shopsphere.controller;import com.shopsphere.model.*;import com.shopsphere.repository.UserRepository;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/users")public class UserController{private final UserRepository repo;public UserController(UserRepository r){repo=r;}@GetMapping @PreAuthorize("hasRole('ADMIN')")public List<AppUser> all(){return repo.findAll();}@DeleteMapping("/{id}")@PreAuthorize("hasRole('ADMIN')")public void delete(@PathVariable Long id){AppUser u=repo.findById(id).orElseThrow();if(u.getRole()==Role.ADMIN)throw new IllegalArgumentException("Admin account cannot be deleted");repo.delete(u);}}